  /** A stable merge sort of {@code ids}. */
  private static void sort(int[] ids, int count, IntOrder order) {
    int[] tmp = new int[count];
    for (int width = 1; width < count; width *= 2) {
      for (int lo = 0; lo < count - width; lo += 2 * width) {
        int mid = lo + width, hi = Math.min(lo + 2 * width, count);
        int i = lo, j = mid, k = lo;
        while (i < mid && j < hi) tmp[k++] = order.compare(ids[i], ids[j]) <= 0 ? ids[i++] : ids[j++];
        while (i < mid) tmp[k++] = ids[i++];
        while (j < hi) tmp[k++] = ids[j++];
        System.arraycopy(tmp, lo, ids, lo, hi - lo);
      }
    }
  }

